let _markdown = "\n\nIntroduction [#introduction]\n\n<FeedbackBlock\n  id=\"72a8c6c7171f57d3\"\n  body=\"Fumadocs offers the MDX Remote package, it is a helper to integrate Markdown/MDX content sources with Fumadocs.\nYou can think it as a next-mdx-remote with built-in plugins for Fumadocs.\"\n>\n  Fumadocs offers the **MDX Remote** package, it is a helper to integrate Markdown/MDX content sources with Fumadocs.\n  You can think it as a `next-mdx-remote` with built-in plugins for Fumadocs.\n</FeedbackBlock>\n\n<Callout type=\"warn\" title=\"Be Careful\">\n  The Passed MDX content must be trusted as it allows code execution by default.\n</Callout>\n\nSetup [#setup]\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install @fumadocs/mdx-remote\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add @fumadocs/mdx-remote\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add @fumadocs/mdx-remote\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add @fumadocs/mdx-remote\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock\n  id=\"72ab1e5c3b3ca70b\"\n  body=\"The main feature it offers is the MDX Compiler, it can compile MDX content to JSX nodes.\nSince it doesn't use a bundler, there's some limitations:\"\n>\n  The main feature it offers is the MDX Compiler, it can compile MDX content to JSX nodes.\n  Since it doesn't use a bundler, there's some limitations:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"8de8acf9b73774e3\" body=\"No imports and exports in MDX files.\">\n  * No imports and exports in MDX files.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"d7b1c91043b45a37\" body=\"It's compatible with Server Components. For example:\">\n  It's compatible with Server Components. For example:\n</FeedbackBlock>\n\n```tsx\nimport { createCompiler } from '@fumadocs/mdx-remote';\nimport { getPage } from './my-content-source';\nimport { DocsBody, DocsPage } from 'fumadocs-ui/layouts/docs/page';\nimport { getMDXComponents } from '@/mdx-components';\n\nconst compiler = createCompiler({\n  // options\n});\n\nexport default async function Page({ params }: { params: { slug?: string[] } }) {\n  const page = getPage(params.slug);\n  const compiled = await compiler.compile({\n    source: page.content,\n  });\n\n  const MdxContent = compiled.body;\n\n  return (\n    <DocsPage toc={compiled.toc}>\n      <DocsBody>\n        <MdxContent components={getMDXComponents()} />\n      </DocsBody>\n    </DocsPage>\n  );\n}\n```\n\nImages [#images]\n\n<FeedbackBlock\n  id=\"d16f2ecbfeca4450\"\n  body=\"On serverless platforms like Vercel, the original public folder (including static assets like images) will be removed after production build.\nThe MDX compiler might no longer be able to access local images in public.\"\n>\n  On serverless platforms like Vercel, the original `public` folder (including static assets like images) will be removed after production build.\n  The MDX compiler might no longer be able to access local images in `public`.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"5124752d98928b58\" body=\"When referencing images, make sure to use a URL.\">\n  When referencing images, make sure to use a URL.\n</FeedbackBlock>\n";
